  color: var(--muted);
}

.log li {
  padding: 0.25rem 0;
  border-top: 1px solid var(--border);
}

.log li:first-child {
  border-top: none;
}

.answer-box {
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
}

.answer-box h3 {
  margin: 0 0 0.5rem;
  font-size: 0.95rem;
}

.citations {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.citation-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 0.6rem 0.75rem;
  font-size: 0.85rem;
}

.citation-card .source-line {
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.citation-card p {
  margin: 0;
  color: var(--muted);
}

.status {
  position: fixed;
  bottom: 1.25rem;
  left: 50%;
  transform: translateX(-50%);
  padding: 0.6rem 1.1rem;
  border-radius: 8px;
  font-size: 0.9rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
}

.status-success {
  background: var(--success-bg);
  color: var(--success-text);
}

.status-error {
  background: var(--error-bg);
  color: var(--error-text);
}

.hidden {
  display: none;
}

